+static bool is_unreserved(unsigned char in)
+{
+  return (in >= 'a' && in <= 'z') ||
+         (in >= 'A' && in <= 'Z') ||
+         (in >= '0' && in <= '9') ||
+         in == '-' || in == '.' || in == '_' || in == '~';
+}
+
 /* Escapes for URL the given unescaped string of given length.
  * 'data' is ignored since 7.82.0.
  */
@@ -179,7 +187,7 @@ char *curl_easy_escape(CURL *curl, const char *string, int length)
   while(len--) {
     uint8_t in = (uint8_t)*string++;

-    if(!(hextable[in] & 0x80))
+    if(is_unreserved(in))
       /* append this */
       nappend++;
     else {

